create table if not exists product_families(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),code text not null check(code~'^[A-Z0-9_]+$'),name text not null,description text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,code),unique(organization_id,id));
create table if not exists product_types(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),code text not null check(code~'^[A-Z0-9_]+$'),name text not null,description text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,code),unique(organization_id,id));
create table if not exists products(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),sku text not null,description text,product_family_id uuid,product_type_id uuid,decoration_method text,default_routing_id uuid,source_system text,source_product_code text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,sku),unique(organization_id,id),foreign key(organization_id,product_family_id)references product_families(organization_id,id),foreign key(organization_id,product_type_id)references product_types(organization_id,id));
create table if not exists product_source_mappings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),source_system text not null,source_product_code text not null,product_id uuid not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,source_system,source_product_code),foreign key(organization_id,product_id)references products(organization_id,id));
create table if not exists operations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),code text not null check(code~'^[A-Z0-9_]+$'),name text not null,description text,operation_type text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,code));
create table if not exists work_centers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),code text not null check(code~'^[A-Z0-9_]+$'),name text not null,description text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,code),unique(organization_id,id));
create table if not exists production_resources(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),work_center_id uuid not null,code text not null check(code~'^[A-Z0-9_-]+$'),name text not null,resource_type text,asset_id uuid references maintenance_assets(id),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,code),foreign key(organization_id,work_center_id)references work_centers(organization_id,id));
create index if not exists products_classification_idx on products(organization_id,product_family_id,product_type_id);create index if not exists production_resources_center_idx on production_resources(organization_id,work_center_id);
do $$declare o uuid;begin for o in select id from organizations loop insert into product_families(organization_id,code,name)values(o,'ADULT_TSHIRTS','Adult T-Shirts'),(o,'KIDS_TSHIRTS','Kids T-Shirts'),(o,'HOODIES_SWEATSHIRTS','Hoodies / Sweatshirts'),(o,'TOTES','Totes'),(o,'ACCESSORIES','Accessories'),(o,'OTHER','Other'),(o,'UNMAPPED','Unmapped')on conflict do nothing;insert into product_types(organization_id,code,name)values(o,'TSHIRT','T-Shirt'),(o,'HOODIE','Hoodie'),(o,'SWEATSHIRT','Sweatshirt'),(o,'TOTE','Tote'),(o,'STICKER','Sticker'),(o,'MAGNET','Magnet'),(o,'COOLER','Cooler'),(o,'KEYRING','Keyring'),(o,'OTHER','Other'),(o,'UNMAPPED','Unmapped')on conflict do nothing;insert into operations(organization_id,code,name)values(o,'PICKING','Picking'),(o,'DTG_PRINT','DTG Print'),(o,'UNDERPRINT','Underprint'),(o,'PUTWALL','Putwall'),(o,'SCREEN_PRINT','Screen Print'),(o,'UV_PRINT','UV Print'),(o,'LAMINATION','Lamination'),(o,'CUTTING','Cutting'),(o,'QC','Quality Control'),(o,'PACKING','Packing'),(o,'DISPATCH','Dispatch')on conflict do nothing;insert into work_centers(organization_id,code,name)values(o,'DTG','DTG'),(o,'UNDERPRINT','Underprint'),(o,'SCREEN_PRINT','Screen Print'),(o,'UV','UV'),(o,'DISPATCH','Dispatch')on conflict do nothing;end loop;end$$;
create or replace view v_product_mix_classification with(security_invoker=true)as select p.organization_id,p.id product_id,p.sku,p.description,coalesce(f.code,'UNMAPPED')product_family_code,coalesce(t.code,'UNMAPPED')product_type_code,p.decoration_method,p.active from products p left join product_families f on f.id=p.product_family_id and f.organization_id=p.organization_id left join product_types t on t.id=p.product_type_id and t.organization_id=p.organization_id;
do $$declare t text;begin foreach t in array array['product_families','product_types','products','product_source_mappings','operations','work_centers','production_resources']loop execute format('alter table %I enable row level security',t);execute format('create policy %I on %I for select to authenticated using(exists(select 1 from maintenance_members m where m.user_id=auth.uid() and m.organization_id=%I.organization_id and m.active))',t||'_read',t,t);execute format('create policy %I on %I for all to authenticated using(exists(select 1 from maintenance_members m where m.user_id=auth.uid() and m.organization_id=%I.organization_id and m.active and m.role in(''admin'',''supervisor''))) with check(exists(select 1 from maintenance_members m where m.user_id=auth.uid() and m.organization_id=%I.organization_id and m.active and m.role in(''admin'',''supervisor'')))',t||'_manage',t,t,t);end loop;end$$;
grant select on product_families,product_types,products,product_source_mappings,operations,work_centers,production_resources,v_product_mix_classification to authenticated;grant insert,update,delete on product_families,product_types,products,product_source_mappings,operations,work_centers,production_resources to authenticated;grant all on product_families,product_types,products,product_source_mappings,operations,work_centers,production_resources to service_role;grant select on v_product_mix_classification to service_role;
create or replace function enforce_production_resource_asset_organization()returns trigger language plpgsql set search_path=public as $$begin if new.asset_id is not null and not exists(select 1 from maintenance_assets a where a.id=new.asset_id and a.organization_id=new.organization_id)then raise exception 'Production resource asset must belong to the same organization';end if;return new;end$$;
drop trigger if exists production_resource_asset_organization on production_resources;create trigger production_resource_asset_organization before insert or update of asset_id,organization_id on production_resources for each row execute function enforce_production_resource_asset_organization();
